package com.sysdesign.modules.catalog.urlshortener;

import java.time.Instant;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.locks.ReentrantLock;

public record ShortUrl(
    String id,
    String payload,
    String status,
    long version,
    Instant createdAt
) {
    public ShortUrl withStatus(String newStatus) {
        return new ShortUrl(id, payload, newStatus, version + 1, createdAt);
    }
}

public class UrlShortenerService {
    private final ConcurrentHashMap<String, ShortUrl> storage = new ConcurrentHashMap<>();
    private final ReentrantLock mutationLock = new ReentrantLock();
    private final AtomicLong transactionCounter = new AtomicLong(0);

    public ShortUrl register(String id, String payload) {
        mutationLock.lock();
        try {
            ShortUrl item = new ShortUrl(id, payload, "ACTIVE", 1L, Instant.now());
            storage.put(id, item);
            transactionCounter.incrementAndGet();
            return item;
        } finally {
            mutationLock.unlock();
        }
    }

    public Optional<ShortUrl> getById(String id) {
        return Optional.ofNullable(storage.get(id));
    }

    public boolean updateStatus(String id, String newStatus) {
        mutationLock.lock();
        try {
            ShortUrl existing = storage.get(id);
            if (existing == null) return false;
            storage.put(id, existing.withStatus(newStatus));
            return true;
        } finally {
            mutationLock.unlock();
        }
    }
}

