        ShortUrl item{id, payload, "ACTIVE", 1, std::chrono::system_clock::now()};
        storage_[id] = item;
        counter_++;
        return item;
    }

    std::optional<ShortUrl> getById(const std::string& id) const {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = storage_.find(id);
        if (it != storage_.end()) {
            return it->second;
        }
        return std::nullopt;
    }
};

