// Go 1.23 High-Performance Implementation
package urlshortener

import (
	"sync"
	"time"
)

type ShortUrl struct {
	ID        string    `json:"id"`
	Payload   string    `json:"payload"`
	Status    string    `json:"status"`
	Version   int64     `json:"version"`
	CreatedAt time.Time `json:"createdAt"`
}

type UrlShortenerService struct {
	mu      sync.RWMutex
	storage map[string]ShortUrl
	counter int64
}

func NewUrlShortenerService() *UrlShortenerService {
	return &UrlShortenerService{
		storage: make(map[string]ShortUrl),
	}
}

func (s *UrlShortenerService) Register(id, payload string) ShortUrl {
	s.mu.Lock()
	defer s.mu.Unlock()

	item := ShortUrl{
		ID:        id,
		Payload:   payload,
		Status:    "ACTIVE",
		Version:   1,
		CreatedAt: time.Now().UTC(),
	}
	s.storage[id] = item
	s.counter++
	return item
}

func (s *UrlShortenerService) GetByID(id string) (*ShortUrl, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()

	item, exists := s.storage[id]
	if !exists {
		return nil, false
	}
	return &item, true
}

