package com.sysdesign.modules.catalog.evcharginggrid;

import java.time.Instant;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.locks.ReentrantLock;

public record ChargingStation(
    String id,
    String payload,
    String status,
    long version,
    Instant createdAt
) {
    public ChargingStation withStatus(String newStatus) {
        return new ChargingStation(id, payload, newStatus, version + 1, createdAt);
    }
}

public class EvGridPowerManager {
    private final ConcurrentHashMap<String, ChargingStation> storage = new ConcurrentHashMap<>();
    private final ReentrantLock mutationLock = new ReentrantLock();
    private final AtomicLong transactionCounter = new AtomicLong(0);

    public ChargingStation register(String id, String payload) {
        mutationLock.lock();
        try {
            ChargingStation item = new ChargingStation(id, payload, "ACTIVE", 1L, Instant.now());
            storage.put(id, item);
            transactionCounter.incrementAndGet();
            return item;
        } finally {
            mutationLock.unlock();
        }
    }

    public Optional<ChargingStation> getById(String id) {
        return Optional.ofNullable(storage.get(id));
    }

    public boolean updateStatus(String id, String newStatus) {
        mutationLock.lock();
        try {
            ChargingStation existing = storage.get(id);
            if (existing == null) return false;
            storage.put(id, existing.withStatus(newStatus));
            return true;
        } finally {
            mutationLock.unlock();
        }
    }
}

