    std::string status;
    int64_t version;
    std::chrono::system_clock::time_point createdAt;
};

class EvGridPowerManager {
private:
    std::unordered_map<std::string, ChargingStation> storage_;
    mutable std::mutex mtx_;
    int64_t counter_ = 0;

public:
    ChargingStation registerItem(const std::string& id, const std::string& payload) {
        std::lock_guard<std::mutex> lock(mtx_);
        ChargingStation item{id, payload, "ACTIVE", 1, std::chrono::system_clock::now()};
        storage_[id] = item;
        counter_++;
        return item;
    }

    std::optional<ChargingStation> getById(const std::string& id) const {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = storage_.find(id);
        if (it != storage_.end()) {
            return it->second;
        }
        return std::nullopt;
    }
};

