// Go 1.23 High-Performance Implementation
package evcharginggrid

import (
	"sync"
	"time"
)

type ChargingStation struct {
	ID        string    `json:"id"`
	Payload   string    `json:"payload"`
	Status    string    `json:"status"`
	Version   int64     `json:"version"`
	CreatedAt time.Time `json:"createdAt"`
}

type EvGridPowerManager struct {
	mu      sync.RWMutex
	storage map[string]ChargingStation
	counter int64
}

func NewEvGridPowerManager() *EvGridPowerManager {
	return &EvGridPowerManager{
		storage: make(map[string]ChargingStation),
	}
}

func (s *EvGridPowerManager) Register(id, payload string) ChargingStation {
	s.mu.Lock()
	defer s.mu.Unlock()

	item := ChargingStation{
		ID:        id,
		Payload:   payload,
		Status:    "ACTIVE",
		Version:   1,
		CreatedAt: time.Now().UTC(),
	}
	s.storage[id] = item
	s.counter++
	return item
}

func (s *EvGridPowerManager) GetByID(id string) (*ChargingStation, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()

	item, exists := s.storage[id]
	if !exists {
		return nil, false
	}
	return &item, true
}

