    private final ConcurrentHashMap<String, BookItem> storage = new ConcurrentHashMap<>();
    private final ReentrantLock mutationLock = new ReentrantLock();
    private final AtomicLong transactionCounter = new AtomicLong(0);

    public BookItem register(String id, String payload) {
        mutationLock.lock();
        try {
            BookItem item = new BookItem(id, payload, "ACTIVE", 1L, Instant.now());
            storage.put(id, item);
            transactionCounter.incrementAndGet();
            return item;
        } finally {
            mutationLock.unlock();
        }
    }

    public Optional<BookItem> getById(String id) {
        return Optional.ofNullable(storage.get(id));
    }

    public boolean updateStatus(String id, String newStatus) {
        mutationLock.lock();
        try {
            BookItem existing = storage.get(id);
            if (existing == null) return false;
            storage.put(id, existing.withStatus(newStatus));
            return true;
        } finally {
            mutationLock.unlock();
        }
    }
}

