// C++ 20 Modern Concurrency Implementation
#pragma once
#include <string>
#include <unordered_map>
#include <mutex>
#include <optional>
#include <chrono>

struct BookItem {
    std::string id;
    std::string payload;
    std::string status;
    int64_t version;
    std::chrono::system_clock::time_point createdAt;
};

class LibraryCatalogManager {
private:
    std::unordered_map<std::string, BookItem> storage_;
    mutable std::mutex mtx_;
    int64_t counter_ = 0;

public:
    BookItem registerItem(const std::string& id, const std::string& payload) {
        std::lock_guard<std::mutex> lock(mtx_);
        BookItem item{id, payload, "ACTIVE", 1, std::chrono::system_clock::now()};
        storage_[id] = item;
        counter_++;
        return item;
    }

    std::optional<BookItem> getById(const std::string& id) const {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = storage_.find(id);
        if (it != storage_.end()) {
            return it->second;
        }
        return std::nullopt;
    }
};

