// Go 1.23 High-Performance Implementation
package librarymanagementlld

import (
	"sync"
	"time"
)

type BookItem struct {
	ID        string    `json:"id"`
	Payload   string    `json:"payload"`
	Status    string    `json:"status"`
	Version   int64     `json:"version"`
	CreatedAt time.Time `json:"createdAt"`
}

type LibraryCatalogManager struct {
	mu      sync.RWMutex
	storage map[string]BookItem
	counter int64
}

func NewLibraryCatalogManager() *LibraryCatalogManager {
	return &LibraryCatalogManager{
		storage: make(map[string]BookItem),
	}
}

func (s *LibraryCatalogManager) Register(id, payload string) BookItem {
	s.mu.Lock()
	defer s.mu.Unlock()

	item := BookItem{
		ID:        id,
		Payload:   payload,
		Status:    "ACTIVE",
		Version:   1,
		CreatedAt: time.Now().UTC(),
	}
	s.storage[id] = item
	s.counter++
	return item
}

func (s *LibraryCatalogManager) GetByID(id string) (*BookItem, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()

	item, exists := s.storage[id]
	if !exists {
		return nil, false
	}
	return &item, true
}
